import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"变量、表达式与占位符上下文矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/variable-contexts.md","filePath":"modules/corelib/variable-contexts.md","lastUpdated":0}`),a={name:`modules/corelib/variable-contexts.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="变量、表达式与占位符上下文矩阵" tabindex="-1">变量、表达式与占位符上下文矩阵 <a class="header-anchor" href="#变量、表达式与占位符上下文矩阵" aria-label="Permalink to “变量、表达式与占位符上下文矩阵”">​</a></h1><p>本页依据当前生产实现中的 parser、service、model 与 PlaceholderAPI expansion 整理，覆盖 CoreLib、Attribute、Strengthen、Skills、Item、Forge、Cooking、Gem、Level、Codex。</p><h2 id="先区分四种同形语法" tabindex="-1">先区分四种同形语法 <a class="header-anchor" href="#先区分四种同形语法" aria-label="Permalink to “先区分四种同形语法”">​</a></h2><p>很多位置都写成 <code>%key%</code>，但它们不是同一套系统：</p><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>解析时机</th></tr></thead><tbody><tr><td>表达式变量</td><td>数值、布尔、随机配置计算</td><td><code>ExpressionEngine</code> 或模块自身解析器求值时</td></tr><tr><td>内部模板变量</td><td>Action、名称、Lore、消息等文本替换</td><td>对应模块构造文本或 ActionContext 时</td></tr><tr><td>PlaceholderAPI 占位符</td><td>给计分板、菜单、聊天等外部插件读取</td><td>PlaceholderAPI 请求时</td></tr><tr><td>运行时上下文</td><td>伤害、玩法事件、技能调用等携带的数据 Map</td><td>由消费该上下文的表达式、条件或模板读取</td></tr></tbody></table><p>同名变量只在其明确作用域内有效。不能因为某个 PAPI 占位符存在，就假定同名短变量可用于模块公式。</p><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to “总览”">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>主要表达式上下文</th><th>内部模板 / Action 上下文</th><th>PlaceholderAPI</th></tr></thead><tbody><tr><td>CoreLib</td><td>调用方 Map、随机配置局部 <code>variables</code></td><td>玩家、阶段、循环与调用方动态键</td><td>无自有扩展，仅负责最后转交 PAPI</td></tr><tr><td>Attribute</td><td>伤害阶段、恢复、DamageContext</td><td>伤害消息</td><td><code>emakiattribute</code></td></tr><tr><td>Strengthen</td><td>货币成本；效果值仅有限引用</td><td>强化展示、成功/失败动作</td><td><code>emakistrengthen</code></td></tr><tr><td>Skills</td><td>技能参数、自定义变量、升级成本</td><td>技能脚本文本、升级消息</td><td><code>emakiskills</code></td></tr><tr><td>Item</td><td>物品构建、EA 属性、修复成本</td><td>物品动作、套装显示</td><td><code>emakiitem</code></td></tr><tr><td>Forge</td><td>材料 stat/EA 属性/容量随机值</td><td>最终物品展示、结果动作</td><td><code>emakiforge</code></td></tr><tr><td>Cooking</td><td>营养 Action 数量表达式</td><td>食谱奖励与营养消息</td><td><code>emakicooking</code></td></tr><tr><td>Gem</td><td>宝石 stat/EA 属性、成本、镶嵌率</td><td>镶嵌/升级/提取结果</td><td><code>emakigem</code></td></tr><tr><td>Level</td><td>升级需求、来源经验、属性、成本</td><td>等级操作与升级结果</td><td><code>emakilevel</code></td></tr><tr><td>Codex</td><td>无自有公式环境；使用 GameplayEvent 条件变量</td><td>触发器与成就完成文本</td><td>无自有扩展</td></tr></tbody></table><h2 id="corelib" tabindex="-1">CoreLib <a class="header-anchor" href="#corelib" aria-label="Permalink to “CoreLib”">​</a></h2><h3 id="通用-expressionengine" tabindex="-1">通用 ExpressionEngine <a class="header-anchor" href="#通用-expressionengine" aria-label="Permalink to “通用 ExpressionEngine”">​</a></h3><p>变量由调用方 Map 注入，写法为 <code>%name%</code>。CoreLib 没有为所有公式自动注入一组全局业务变量。</p><ul><li>运算符：<code>+</code>、<code>-</code>、<code>*</code>、<code>/</code>、<code>%</code>、<code>^</code>、括号。</li><li>函数：<code>ceil</code>、<code>floor</code>、<code>round</code>、<code>log10</code>、<code>min</code>、<code>max</code>、<code>pow</code>。</li><li>最大表达式长度 256 字符，最大递归深度 10。</li><li>禁止反引号、<code>$</code>、反斜杠。</li><li>缺失变量、自引用、非数值变量、<code>NaN</code> 或无限结果会使详细求值失败；简化接口通常回退为 <code>0</code>。</li><li>随机配置自身的 <code>variables</code> 会覆盖外部同名变量；动态变量按实际 Map 迭代顺序求值，后项可引用已经解析的前项。</li></ul><p>实现依据：<code>ExpressionEngine</code>、<code>ExpressionRules</code>、<code>RandomExpressionEvaluator</code>、<code>BooleanExpressionEvaluator</code>。</p><h3 id="actioncontext-内部变量" tabindex="-1">ActionContext 内部变量 <a class="header-anchor" href="#actioncontext-内部变量" aria-label="Permalink to “ActionContext 内部变量”">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>%player%</code>、<code>%player_name%</code></td><td>玩家名称</td></tr><tr><td><code>%player_uuid%</code></td><td>玩家 UUID</td></tr><tr><td><code>%player_world%</code></td><td>世界名</td></tr><tr><td><code>%player_x%</code>、<code>%player_y%</code>、<code>%player_z%</code></td><td>玩家坐标</td></tr><tr><td><code>%phase%</code></td><td>当前动作阶段</td></tr><tr><td><code>&lt;show_item&gt;</code></td><td>独立内联 token；仅在上下文存在 <code>show_item</code> 时替换</td></tr></tbody></table><p>以上 8 个变量是 CoreLib 唯一自动注入的一组。没有 <code>%template_&lt;key&gt;%</code>，也没有 <code>%loop_*%</code> 系列变量：传给命名序列的额外参数在序列体内读作 <code>%var.&lt;名字&gt;%</code>。</p><p>调用模块还可通过 <code>ActionContext.placeholders()</code> 注入任意小写键。<code>attributes()</code> 不会自动转成模板变量。</p><p>实现依据：<code>PlaceholderRenderer</code>、<code>ActionInlineTokenResolver</code>。</p><h3 id="gameplayevent-变量" tabindex="-1">GameplayEvent 变量 <a class="header-anchor" href="#gameplayevent-变量" aria-label="Permalink to “GameplayEvent 变量”">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>变量</th></tr></thead><tbody><tr><td>方块破坏 / 放置</td><td><code>block_type</code></td></tr><tr><td>实体击杀 / 驯服</td><td><code>entity_type</code></td></tr><tr><td>MythicMobs 击杀</td><td><code>mythic_id</code>、<code>mythic_level</code></td></tr><tr><td>合成 / 熔炉取出</td><td><code>result_type</code>、<code>result_amount</code></td></tr><tr><td>钓鱼</td><td><code>fish_state</code></td></tr><tr><td>酿造完成</td><td><code>potion_type</code></td></tr></tbody></table><p>这些键来自真实 Bukkit 事件，并由 Level、Codex 等模块按事件类型消费。</p><h3 id="placeholderapi-边界" tabindex="-1">PlaceholderAPI 边界 <a class="header-anchor" href="#placeholderapi-边界" aria-label="Permalink to “PlaceholderAPI 边界”">​</a></h3><p>CoreLib 不注册自己的 PlaceholderAPI expansion。解析链先处理内部变量与内联 token，再在安装 PlaceholderAPI 且存在玩家上下文时转交外部解析。</p><h2 id="attribute" tabindex="-1">Attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to “Attribute”">​</a></h2><h3 id="自定义伤害阶段-stages-expression" tabindex="-1">自定义伤害阶段 <code>stages[].expression</code> <a class="header-anchor" href="#自定义伤害阶段-stages-expression" aria-label="Permalink to “自定义伤害阶段 stages[].expression”">​</a></h3><p>仅 <code>CUSTOM</code> 阶段使用表达式。</p><table tabindex="0"><thead><tr><th>变量</th><th>语义 / 单位</th></tr></thead><tbody><tr><td><code>input</code>、<code>base</code></td><td>进入当前阶段的伤害点</td></tr><tr><td><code>flat</code></td><td>固定属性聚合值</td></tr><tr><td><code>percent</code></td><td>百分比点</td></tr><tr><td><code>chance</code></td><td>触发概率，<code>0..100</code></td></tr><tr><td><code>multiplier</code></td><td>倍率属性的百分比点</td></tr><tr><td><code>roll</code></td><td>当前判定随机值，<code>0..100</code></td></tr><tr><td><code>crit</code></td><td>是否触发，<code>1</code> 或 <code>0</code></td></tr><tr><td>DamageContext 任意键</td><td>调用方或伤害服务写入的运行时上下文</td></tr></tbody></table><p>重要边界：实现先写入上述固定键，再合并 DamageContext。因此 DamageContext 中的同名键会覆盖固定键。<code>ATTACKER</code> / <code>TARGET</code> 来源先读属性快照，缺失时可回退到上下文同名数值；<code>CONTEXT</code> 来源只读取上下文。</p><p>实现依据：<code>StageCalculator</code>、<code>DamageContextVariables</code>。</p><h3 id="damagecontext-标准键" tabindex="-1">DamageContext 标准键 <a class="header-anchor" href="#damagecontext-标准键" aria-label="Permalink to “DamageContext 标准键”">​</a></h3><ul><li>实体：<code>attacker</code>、<code>attacker_name</code>、<code>attacker_type</code>、<code>attacker_uuid</code>、<code>source</code>、<code>source_name</code>、<code>target</code>、<code>target_name</code>、<code>target_type</code>、<code>target_uuid</code>。</li><li>伤害类型：<code>damage_type</code>、<code>damage_type_name</code>、<code>damage_type_id</code>。</li><li>伤害数值：<code>source_damage</code>、<code>input_damage</code>、<code>base_damage</code>、<code>damage</code>、<code>final_damage</code>。</li><li>原因：<code>cause</code>、<code>cause_name</code>、<code>cause_id</code>、<code>damage_cause</code>、<code>damage_cause_name</code>、<code>damage_cause_id</code>。</li><li>投射物：<code>projectile_type</code>、<code>projectile_uuid</code>。</li><li>控制：<code>allow_critical</code>、<code>allow_target_dodge</code>、<code>calculate_target_defense</code>。</li><li>随机：<code>damage_roll</code>、<code>damage_roll_flat</code>、<code>damage_roll_percent</code>、<code>damage_roll_chance</code>、<code>damage_roll_multiplier</code>，范围 <code>0..1</code>。</li><li>闪避：<code>dodge_chance</code>、<code>dodge_roll</code>、<code>dodged</code>，概率/随机值范围 <code>0..100</code>。</li><li>摔落：<code>fall_distance</code>、<code>jump_boost_level</code>、<code>vanilla_fall_damage</code>、<code>fall_damage_formula</code>。</li></ul><p>键在 <code>DamageContextVariables</code> 中会规范化为小写 identifier。</p><h3 id="恢复公式-recovery-expression" tabindex="-1">恢复公式 <code>recovery.expression</code> <a class="header-anchor" href="#恢复公式-recovery-expression" aria-label="Permalink to “恢复公式 recovery.expression”">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>input</code>、<code>base</code>、<code>damage</code>、<code>final_damage</code></td><td>最终伤害点</td></tr><tr><td><code>flat</code>、<code>healing_flat</code></td><td>固定恢复点数</td></tr><tr><td><code>percent</code>、<code>healing_percent</code></td><td>恢复百分比点</td></tr><tr><td><code>percent_amount</code>、<code>healing_percent_amount</code></td><td>按伤害折算的恢复量</td></tr><tr><td><code>gross</code>、<code>healing_gross</code></td><td>抗性前总恢复量</td></tr><tr><td><code>resistance</code>、<code>healing_resistance</code></td><td>恢复抗性百分比点</td></tr></tbody></table><p>恢复固定键在继承 DamageContext 后写入，因此会覆盖上下文同名键。默认结果为 <code>gross * (1 - resistance / 100)</code>，随后应用最小/最大值并钳制为非负。</p><p>实现依据：<code>DamageRecoveryCalculator</code>。</p><h3 id="伤害消息模板" tabindex="-1">伤害消息模板 <a class="header-anchor" href="#伤害消息模板" aria-label="Permalink to “伤害消息模板”">​</a></h3><p><code>message</code>、<code>attacker_message</code>、<code>target_message</code> 使用普通 <code>%key%</code> 文本替换。除上述实体、伤害类型、伤害数值与原因键外，还提供：</p><p><code>source_type</code>、<code>source_uuid</code>、<code>critical</code>、<code>critical_text</code>、<code>critical_suffix</code>、<code>roll</code>、<code>attacker_health</code>、<code>attacker_max_health</code>、<code>target_health</code>、<code>target_max_health</code>、<code>distance</code>。</p><p>健康值与距离只从 DamageContext 读取；未注入时显示为 <code>0</code>。</p><p>实现依据：<code>DamageMessageDispatcher</code>。</p><h3 id="placeholderapi-emakiattribute" tabindex="-1">PlaceholderAPI：<code>emakiattribute</code> <a class="header-anchor" href="#placeholderapi-emakiattribute" aria-label="Permalink to “PlaceholderAPI：emakiattribute”">​</a></h3><ul><li><code>%emakiattribute_&lt;attribute_id&gt;%</code></li><li><code>%emakiattribute_power%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_current%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_max%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_default%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_bonus%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_percent%</code></li><li><code>%emakiattribute_resource_&lt;id&gt;_regen%</code></li></ul><p>资源解析会把第一个下划线前的文本视为资源 ID，因此资源 ID 建议不要包含下划线。</p><h2 id="strengthen" tabindex="-1">Strengthen <a class="header-anchor" href="#strengthen" aria-label="Permalink to “Strengthen”">​</a></h2><h3 id="成功率" tabindex="-1">成功率 <a class="header-anchor" href="#成功率" aria-label="Permalink to “成功率”">​</a></h3><p>成功率不是 ExpressionEngine 公式。实际计算为目标星基础成功率，加上有效锻印等级乘每级加成，最后限制到 <code>0..success_chance_cap</code>。</p><p>实现依据：<code>ChanceCalculator</code>。</p><h3 id="货币成本-cost-formula" tabindex="-1">货币成本 <code>cost_formula</code> <a class="header-anchor" href="#货币成本-cost-formula" aria-label="Permalink to “货币成本 cost_formula”">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>base_cost</code></td><td>货币基础成本</td></tr><tr><td><code>star</code></td><td>目标星级，即当前星级 + 1</td></tr></tbody></table><p>公式结果必须有限且大于 <code>0</code>，然后四舍五入为整数成本；否则该成本项会被跳过。</p><h3 id="效果值解析边界" tabindex="-1">效果值解析边界 <a class="header-anchor" href="#效果值解析边界" aria-label="Permalink to “效果值解析边界”">​</a></h3><p><code>stars.&lt;n&gt;.variables</code>、<code>effects[type=variables].variables</code>、<code>ea_attributes</code> 的生产实现只支持：</p><ul><li>Number；</li><li>数值字符串；</li><li>整个值恰好为 <code>%name%</code> 的引用。</li></ul><p><code>%star% * 2</code> 这类算术文本不会进入 CoreLib ExpressionEngine，会回退为 <code>0</code>。初始固定变量只有 <code>star</code>，后续动态键能否引用前项取决于实际 Map 迭代顺序。</p><p>实现依据：<code>StrengthenRecipe.resolveExpressions</code>、<code>StrengthenApiValues.evaluateNumber/evaluateMixed</code>。</p><h3 id="展示与动作变量" tabindex="-1">展示与动作变量 <a class="header-anchor" href="#展示与动作变量" aria-label="Permalink to “展示与动作变量”">​</a></h3><p>展示提供动态 stat 键，以及 <code>star</code>、<code>temper</code>、<code>max_temper</code>、<code>temper_color</code>；属性行另有 <code>id</code>、<code>sign</code>、<code>value</code>。</p><p>成功/失败 Action 提供：</p><p><code>operation_id</code>、<code>strengthen_operation_id</code>、<code>strengthen_recipe_id</code>、<code>strengthen_recipe</code>、<code>strengthen_star</code>、<code>strengthen_temper</code>、<code>strengthen_show_item</code>、<code>strengthen_result_slot</code>、<code>strengthen_max_star</code>、<code>strengthen_success_rate</code>、<code>show_item</code>、<code>star</code>、<code>temper</code>、<code>dropped</code>、<code>protected</code>、<code>was_star</code>。</p><p>实现依据：<code>StrengthenSnapshotBuilder</code>、<code>StrengthenActionCoordinator</code>。</p><h3 id="placeholderapi-emakistrengthen" tabindex="-1">PlaceholderAPI：<code>emakistrengthen</code> <a class="header-anchor" href="#placeholderapi-emakistrengthen" aria-label="Permalink to “PlaceholderAPI：emakistrengthen”">​</a></h3><p><code>mainhand_star</code>、<code>mainhand_temper</code>、<code>mainhand_recipe</code>、<code>mainhand_eligible</code>、<code>mainhand_success_count</code>、<code>mainhand_failure_count</code>、<code>mainhand_max_star</code>、<code>mainhand_success_rate</code>、<code>mainhand_crack_level</code>。</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to “Skills”">​</a></h2><h3 id="技能变量" tabindex="-1">技能变量 <a class="header-anchor" href="#技能变量" aria-label="Permalink to “技能变量”">​</a></h3><p><code>variables.*</code> 使用：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>level</code>、<code>target_level</code>、<code>max_level</code></td><td>技能等级上下文</td></tr><tr><td><code>skill_id</code>、<code>trigger_id</code></td><td>技能与触发器 ID</td></tr><tr><td><code>is_passive</code></td><td>是否被动技能，<code>1/0</code></td></tr><tr><td><code>player_level</code></td><td>原版经验等级</td></tr><tr><td><code>player_health</code>、<code>player_max_health</code></td><td>Bukkit 生命点</td></tr><tr><td><code>sneaking</code>、<code>has_target</code></td><td>布尔量，<code>1/0</code></td></tr></tbody></table><p>技能自定义 <code>variables</code> 还可引用已经解析的参数和此前自定义变量。参数本身不会自动获得其他参数的求值结果，<code>TriggerInvocation.extraVariables()</code> 当前也未合并进这套解析环境。</p><p>实现依据：<code>SkillParameterResolver</code>、<code>SkillVariableResolver</code>。</p><h3 id="升级成本与文本" tabindex="-1">升级成本与文本 <a class="header-anchor" href="#升级成本与文本" aria-label="Permalink to “升级成本与文本”">​</a></h3><p>升级货币 <code>cost_formula</code> 使用上述固定上下文，并额外提供 <code>base_cost</code>；调用时 <code>trigger_id=upgrade</code>。升级成功率来自静态成功率表，不是公式。</p><p>技能脚本文本可使用 <code>level</code>、<code>skill_id</code>、<code>trigger_id</code>、<code>has_target</code>，以及已解析参数和自定义动态键。升级消息提供 <code>player</code>、<code>skill_id</code>、<code>skill</code>（技能显示名）、<code>level</code>、<code>current_level</code>、<code>target_level</code>、<code>max_level</code>、<code>success_rate</code>、<code>success_rate_raw</code>、<code>roman_level</code> 和成本/结果动态键。</p><h3 id="placeholderapi-emakiskills" tabindex="-1">PlaceholderAPI：<code>emakiskills</code> <a class="header-anchor" href="#placeholderapi-emakiskills" aria-label="Permalink to “PlaceholderAPI：emakiskills”">​</a></h3><ul><li>全局：<code>cast_mode</code>、<code>global_cooldown</code>、<code>unlocked_count</code>、<code>slot_count</code>、<code>level_total</code>。</li><li>技能：<code>level_&lt;skill_id&gt;</code>、<code>cooldown_&lt;skill_id&gt;</code>。</li><li>槽位：<code>slot_&lt;index&gt;_skill|name|trigger|empty</code>。</li><li>资源：<code>resource_&lt;id&gt;_current|max|percent</code>。</li></ul><p>冷却单位为秒，槽位使用从 0 开始的索引。</p><h2 id="item" tabindex="-1">Item <a class="header-anchor" href="#item" aria-label="Permalink to “Item”">​</a></h2><h3 id="物品构建变量" tabindex="-1">物品构建变量 <a class="header-anchor" href="#物品构建变量" aria-label="Permalink to “物品构建变量”">​</a></h3><p>顶层 <code>variables</code> 与 <code>effects[type=variables].variables</code> 没有固定内置变量，从空 Map 按顺序解析。名称、Lore、结构化展示与原版 attribute modifier 可读取这些动态键。</p><p><code>ea_attributes</code> 和 <code>effects[type=ea_attribute].ea_attributes</code> 使用独立的空上下文顺序解析，不继承顶层 <code>variables</code>。不要在 EA 属性表达式中引用顶层构建变量。</p><p>实现依据：<code>EmakiItemDefinitionParser</code>、<code>EmakiItemFactory</code>、<code>EmakiItemPdcWriter</code>。</p><h3 id="修复成本" tabindex="-1">修复成本 <a class="header-anchor" href="#修复成本" aria-label="Permalink to “修复成本”">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>max_damage</code></td><td>最大耐久</td></tr><tr><td><code>damage</code>、<code>current_damage</code>、<code>missing_durability</code></td><td>当前缺失耐久点</td></tr><tr><td><code>missing_ratio</code></td><td>缺失比例，<code>0..1</code></td></tr><tr><td><code>restore_amount</code></td><td>本次恢复耐久点</td></tr><tr><td><code>restore_ratio</code></td><td>恢复比例，<code>0..1</code></td></tr><tr><td><code>base_cost</code></td><td>货币基础成本</td></tr></tbody></table><p>实现依据：<code>ItemRepairService</code>。</p><h3 id="动作、套装与-placeholderapi" tabindex="-1">动作、套装与 PlaceholderAPI <a class="header-anchor" href="#动作、套装与-placeholderapi" aria-label="Permalink to “动作、套装与 PlaceholderAPI”">​</a></h3><p>物品 Action：<code>player</code>、<code>item_id</code>、<code>item_trigger</code>、<code>item_name</code>。</p><p>套装上下文：<code>item_id</code>、<code>set_id</code>、<code>piece_id</code>、<code>set_name</code>、<code>active</code>、<code>active_count</code>、<code>total</code>、<code>total_pieces</code>、<code>active_thresholds</code>。</p><p><code>emakiitem</code> PAPI：<code>held_id</code>、<code>held_name</code>、<code>held_components</code>、<code>held_components_raw</code>、<code>loaded_count</code>，以及 <code>held_component_has_&lt;id&gt;</code>、<code>held_component_value_&lt;id&gt;</code>、<code>held_component_json_&lt;id&gt;</code>。</p><h2 id="forge" tabindex="-1">Forge <a class="header-anchor" href="#forge" aria-label="Permalink to “Forge”">​</a></h2><h3 id="材料数值上下文" tabindex="-1">材料数值上下文 <a class="header-anchor" href="#材料数值上下文" aria-label="Permalink to “材料数值上下文”">​</a></h3><ul><li><code>capacity_cost</code> 与 <code>capacity_bonus.value</code> 可使用随机数值配置，但没有变量上下文；结果四舍五入为容量整数。</li><li><code>effects[type=variables].variables</code> 每种材料从空 Map 开始，后项可引用当前材料此前 stat 动态键。</li><li><code>effects[type=ea_attribute].ea_attributes</code> 使用另一套独立空 Map，不继承 stat 变量。</li></ul><p>未发现独立的锻造成功率、品质概率或货币成本 ExpressionEngine 公式。</p><h3 id="展示与动作" tabindex="-1">展示与动作 <a class="header-anchor" href="#展示与动作" aria-label="Permalink to “展示与动作”">​</a></h3><p>最终名称/Lore 提供所有最终 stat 动态键，以及 <code>quality</code>、<code>quality_name</code>、<code>quality_multiplier</code>、<code>multiplier</code>。</p><p>结果 Action 提供：<code>forge_recipe_id</code>、<code>forge_recipe_name</code>、<code>forge_source_item_name</code>、<code>forge_result_item_name</code>、<code>forge_quality</code>、<code>forge_multiplier</code>、<code>forge_multiplier_raw</code>、<code>forge_error_key</code>、<code>forge_failure_reason</code>、<code>forge_show_item</code>、<code>show_item</code>。</p><p>实现依据：<code>ForgeMaterial</code>、<code>ForgeStatContributionBuilder</code>、<code>ForgeResultPostProcessor</code>、<code>ForgeActionCoordinator</code>。</p><h3 id="placeholderapi-emakiforge" tabindex="-1">PlaceholderAPI：<code>emakiforge</code> <a class="header-anchor" href="#placeholderapi-emakiforge" aria-label="Permalink to “PlaceholderAPI：emakiforge”">​</a></h3><p><code>recipe_count</code>、<code>craft_count_&lt;recipe_id&gt;</code>、<code>has_crafted_&lt;recipe_id&gt;</code>、<code>total_crafts</code>、<code>last_crafted</code>、<code>guarantee_&lt;key&gt;</code>。</p><h2 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Permalink to “Cooking”">​</a></h2><h3 id="表达式与内部变量" tabindex="-1">表达式与内部变量 <a class="header-anchor" href="#表达式与内部变量" aria-label="Permalink to “表达式与内部变量”">​</a></h3><p>食谱生产链未发现通用 ExpressionEngine 公式。营养操作 Action 的 <code>amount</code> 可写表达式，变量来自当前 ActionContext 中能够转换为数字的 placeholder 与 attribute 动态键；没有额外固定变量。单位为营养点，异常回退为 <code>0</code>。</p><p>食谱奖励 Action：<code>recipe_id</code>、<code>recipe_name</code>、<code>station_type</code>、<code>cooking_recipe_id</code>、<code>cooking_recipe_name</code>、<code>cooking_station_type</code>、<code>cooking_outcome</code>。</p><p>营养消息：动态 <code>nutrition_&lt;type&gt;</code>、<code>nutrition_&lt;type&gt;_max</code>、<code>nutrition_&lt;type&gt;_min</code>，以及 <code>nutrition_type</code>、<code>nutrition_value</code>、<code>nutrition_threshold</code>、<code>nutrition_combo_count</code>、<code>nutrition_combo_required</code>。</p><p>实现依据：<code>NutritionOperationAction</code>、<code>RunRecipeRewardAction</code>、<code>NutritionService</code>。</p><h3 id="placeholderapi-emakicooking" tabindex="-1">PlaceholderAPI：<code>emakicooking</code> <a class="header-anchor" href="#placeholderapi-emakicooking" aria-label="Permalink to “PlaceholderAPI：emakicooking”">​</a></h3><ul><li>配方数：<code>recipe_count</code>、<code>recipe_count_&lt;station_type&gt;</code>。</li><li>营养：<code>nutrition_&lt;type&gt;</code>、<code>nutrition_&lt;type&gt;_max|min</code>、<code>nutrition_combo_count_&lt;rule_id&gt;</code>。</li><li>工位：<code>station_[&lt;type&gt;_]type|type_name|world|x|y|z|location|block|heat_block|burning|burning_seconds|heat|moisture|steam|input|input_source|input_amount|ingredient_count|recipe|recipe_id|progress|progress_target|progress_percent|completed|fluid|fluid_amount|player</code>。</li></ul><p><code>fluid_amount</code> 单位为 ml，<code>burning_seconds</code> 单位为秒。</p><h2 id="gem" tabindex="-1">Gem <a class="header-anchor" href="#gem" aria-label="Permalink to “Gem”">​</a></h2><h3 id="宝石数值与成本" tabindex="-1">宝石数值与成本 <a class="header-anchor" href="#宝石数值与成本" aria-label="Permalink to “宝石数值与成本”">​</a></h3><table tabindex="0"><thead><tr><th>入口</th><th>变量</th></tr></thead><tbody><tr><td>宝石 <code>variables</code> / <code>ea_attributes</code></td><td><code>level</code>，以及此前解析的同类动态键</td></tr><tr><td>共鸣 EA 属性</td><td>无固定初始键，仅此前共鸣属性键</td></tr><tr><td><code>inlay_success.rate_formula</code></td><td><code>default_chance</code>、<code>level_chance</code>、<code>configured_chance</code>、<code>level</code></td></tr><tr><td>镶嵌/提取/升级 <code>cost_formula</code></td><td><code>level</code>、<code>current_level</code>、<code>target_level</code>、<code>base_cost</code></td></tr></tbody></table><p>镶嵌率单位是百分比点，结果限制到 <code>0..100</code>。升级成功率来自静态等级成功率表，不是公式。成本固定 <code>amount &gt;= 0</code> 时优先固定值，否则公式结果钳制非负。</p><p>实现依据：<code>GemDefinition</code>、<code>GemResonanceLoader</code>、<code>GemInlayService</code>、<code>GemExtractService</code>、<code>GemUpgradeService</code>。</p><h3 id="操作变量与-placeholderapi" tabindex="-1">操作变量与 PlaceholderAPI <a class="header-anchor" href="#操作变量与-placeholderapi" aria-label="Permalink to “操作变量与 PlaceholderAPI”">​</a></h3><p>升级、镶嵌、提取链按场景提供 <code>player</code>、<code>gem_id</code>、<code>gem</code>（宝石显示名）、<code>level</code>、<code>current_level</code>、<code>target_level</code>、<code>success_rate</code>、<code>slot</code> 等；宝石展示上下文另有 <code>display_name</code>、<code>old_display_name</code>、<code>gem_type</code> 与各等级 stat 动态键。货币消息提供 <code>provider</code>、<code>currency</code>、<code>currency_id</code>、<code>name</code>、<code>display_name</code>、<code>required</code>、<code>available</code>；材料消息提供 <code>item</code>、<code>material</code>、<code>display_name</code>、<code>required</code>、<code>available</code>。</p><p><code>emakigem</code> PAPI：<code>mainhand_opened_slots</code>、<code>mainhand_total_slots</code>、<code>mainhand_filled_slots</code>、<code>mainhand_item_definition_id</code>、<code>mainhand_resonance_count</code>，以及 <code>mainhand_slot_&lt;index&gt;_gem|level|opened|type</code>。</p><h2 id="level" tabindex="-1">Level <a class="header-anchor" href="#level" aria-label="Permalink to “Level”">​</a></h2><h3 id="升级需求与成本" tabindex="-1">升级需求与成本 <a class="header-anchor" href="#升级需求与成本" aria-label="Permalink to “升级需求与成本”">​</a></h3><table tabindex="0"><thead><tr><th>入口</th><th>变量</th></tr></thead><tbody><tr><td>升级经验需求 <code>formula</code></td><td><code>current_level</code>、<code>target_level</code>、<code>max_level</code>、<code>exp</code>、<code>total_exp</code></td></tr><tr><td>等级属性 <code>attributes.&lt;id&gt;</code></td><td><code>level</code>、<code>exp</code>、<code>total_exp</code></td></tr><tr><td>升级货币/材料成本</td><td><code>target_level</code>、<code>type</code>、<code>base_cost</code>、<code>base_amount</code></td></tr></tbody></table><p>固定 <code>values.&lt;target_level&gt;</code> 优先于需求公式。需求和货币结果钳制非负，材料数量四舍五入为非负整数。</p><h3 id="来源经验" tabindex="-1">来源经验 <a class="header-anchor" href="#来源经验" aria-label="Permalink to “来源经验”">​</a></h3><p><code>exp_formula</code> 只获得当前 GameplayEvent 实际携带的键，不会自动追加统一玩家/等级变量：</p><ul><li>实体：<code>entity_type</code>。</li><li>MythicMobs：<code>mythic_id</code>、<code>mythic_level</code>。</li><li>方块：<code>block_type</code>。</li><li>合成/熔炉：<code>result_type</code>、<code>result_amount</code>。</li><li>钓鱼：<code>fish_state</code>。</li><li>酿造：<code>potion_type</code>。</li></ul><p>Mythic drop 公式另有 <code>amount</code>、<code>drop_amount</code>、<code>metadata_amount</code>、<code>generations</code>、<code>tick</code>，并携带文本上下文 <code>player</code>、<code>type</code>、<code>drop</code>。</p><p>Level operation Action 的 <code>amount</code> 与 Cooking 营养动作相同：只读取 ActionContext 中能转为数字的动态键，没有额外固定变量。</p><p>实现依据：<code>RequirementService</code>、<code>SourceExperienceService</code>、<code>LevelGameplaySubscriber</code>、<code>LevelAttributeBridge</code>、<code>PlayerLevelService</code>、<code>MythicLevelDropBridge</code>、<code>LevelOperationAction</code>。</p><h3 id="placeholderapi-emakilevel" tabindex="-1">PlaceholderAPI：<code>emakilevel</code> <a class="header-anchor" href="#placeholderapi-emakilevel" aria-label="Permalink to “PlaceholderAPI：emakilevel”">​</a></h3><ul><li>玩家：<code>level_&lt;type&gt;</code>、<code>exp_&lt;type&gt;</code>、<code>total_exp_&lt;type&gt;</code>、<code>totalexp_&lt;type&gt;</code>、<code>total_&lt;type&gt;</code>、<code>required_exp_&lt;type&gt;</code>、<code>requiredexp_&lt;type&gt;</code>、<code>required_&lt;type&gt;</code>、<code>progress_&lt;type&gt;</code>、<code>progress_percent_&lt;type&gt;</code>。</li><li>排行：<code>top_&lt;type&gt;_&lt;rank&gt;_name|level|total_exp|totalexp|total</code>。</li></ul><p>排行榜 parser 按下划线分段，类型 ID 建议不要包含下划线。</p><h2 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to “Codex”">​</a></h2><p>Codex 不调用自己的 ExpressionEngine，也不注册 PlaceholderAPI expansion。</p><h3 id="成就触发条件" tabindex="-1">成就触发条件 <a class="header-anchor" href="#成就触发条件" aria-label="Permalink to “成就触发条件”">​</a></h3><p>触发条件使用 CoreLib <code>ConditionEvaluator</code>，变量来自 GameplayEvent，并额外提供 <code>player</code>、<code>world</code>：</p><p><code>block_type</code>、<code>entity_type</code>、<code>mythic_id</code>、<code>mythic_level</code>、<code>result_type</code>、<code>result_amount</code>、<code>fish_state</code>、<code>potion_type</code>、<code>player</code>、<code>world</code>。</p><p>实际可用键取决于事件类型，不会同时全部存在。</p><h3 id="触发器与完成文本" tabindex="-1">触发器与完成文本 <a class="header-anchor" href="#触发器与完成文本" aria-label="Permalink to “触发器与完成文本”">​</a></h3><p>触发/action 行可读取当前事件键。成就完成上下文另有 <code>advancement_id</code>、<code>advancement_node</code>、<code>advancement_title</code>、<code>advancement_page</code>（四个固定键）。</p><p>Codex 先执行本地 <code>%key%</code> 替换；有玩家且安装 PlaceholderAPI 时，再消费其他插件注册的外部占位符。</p><p>实现依据：<code>CodexGameplaySubscriber</code>、<code>CodexTriggerService</code>、<code>AdvancementListener</code>。</p><h2 id="配置时的通用检查清单" tabindex="-1">配置时的通用检查清单 <a class="header-anchor" href="#配置时的通用检查清单" aria-label="Permalink to “配置时的通用检查清单”">​</a></h2><ol><li>先确认当前位置属于公式、内部模板、PAPI 还是运行时上下文。</li><li>只使用本页对应作用域列出的固定键与该配置明确产生的动态键。</li><li>百分比可能使用 <code>0..1</code> 或 <code>0..100</code>；以对应模块说明为准。</li><li>动态键按 Map 顺序求值的模块，不要依赖未经验证的 YAML/Map 重排行为。</li><li>Attribute、Level 等动态 ID parser 对下划线支持不一致，资源/排行 ID 优先使用不含下划线的形式。</li><li>若变量来自事件，必须为不同事件配置分别处理缺失键。</li></ol>`,139)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};